import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderCancellationMailTest {

    @Test
    void cancellingAnOrderMailsTheCustomerOnce() {
        PrintStream original = System.out;
        ByteArrayOutputStream captured = new ByteArrayOutputStream();
        System.setOut(new PrintStream(captured, true, StandardCharsets.UTF_8));
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            CustomerFacade customers = shop.getBean(CustomerFacade.class);
            customers.register("c-1", "anna@shop.example");

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);
            orders.cancel(id);
        } finally {
            System.setOut(original);
        }

        String out = captured.toString(StandardCharsets.UTF_8);
        String expected = "mail to anna@shop.example: Order ";
        assertEquals(1, out.split(java.util.regex.Pattern.quote(expected), -1).length - 1, out);
        assertEquals(1, out.lines().filter(l -> l.startsWith("mail to ")).count(), out);
    }
}
}
